using System.ComponentModel;
using Microsoft.Extensions.AI;

// Configure the chat client with tool support
var chatClient = new ChatClientBuilder(
    new OpenAI.OpenAIClient(Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "your-api-key")
        .GetChatClient("gpt-4o")
        .AsIChatClient())
    .UseFunctionInvocation()
    .Build();

// Define the tools available to the agent
var searchTool = AIFunctionFactory.Create(WebSearch, "web_search", "Searches the web for information on a given query and returns relevant results.");
var addNoteTool = AIFunctionFactory.Create(AddNote, "add_note", "Saves a research note with a title and content for later summarization.");
var getNotesTool = AIFunctionFactory.Create(GetNotes, "get_notes", "Retrieves all saved research notes.");

var notes = new List<ResearchNote>();

// Run the research agent loop
var topic = args.Length > 0 ? string.Join(" ", args) : "the impact of quantum computing on cryptography";
Console.WriteLine($"Research Agent Starting...\nResearching topic: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a given topic thoroughly.
        Use the web_search tool to find information, and the add_note tool to save
        important findings. After gathering enough information (at least 3 searches),
        use get_notes to review your findings, then provide a comprehensive summary.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

var options = new ChatOptions
{
    Tools = [searchTool, addNoteTool, getNotesTool]
};

var response = await chatClient.GetResponseAsync(messages, options);
Console.WriteLine("\n=== Research Summary ===\n");
Console.WriteLine(response.Text);

// --- Tool implementations ---

[Description("Searches the web for information on a given query")]
static string WebSearch(string query)
{
    Console.WriteLine($"  [Searching] \"{query}\"");
    // Simulated search results for demonstration
    return $"""
        Search results for "{query}":
        1. According to recent research papers and articles, {query} is an active area of study.
        2. Experts in the field suggest that developments in this area could have significant implications.
        3. A 2025 survey found growing interest and investment in topics related to {query}.
        (Note: These are simulated results. Connect a real search API for production use.)
        """;
}

[Description("Saves a research note")]
string AddNote(string title, string content)
{
    notes.Add(new ResearchNote(title, content, DateTime.UtcNow));
    Console.WriteLine($"  [Note saved] {title}");
    return $"Note '{title}' saved successfully.";
}

[Description("Retrieves all saved research notes")]
string GetNotes()
{
    if (notes.Count == 0)
        return "No notes have been saved yet.";

    return string.Join("\n\n", notes.Select((n, i) =>
        $"--- Note {i + 1}: {n.Title} ---\n{n.Content}\n[Saved at {n.Timestamp:u}]"));
}

record ResearchNote(string Title, string Content, DateTime Timestamp);

